head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setTopRowIndex(7);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setGridHeight(100);
};
scwin.trigger3_onclick = function(e) {
    gridView1.setGridHeight(200);
};
scwin.gridView2_onscrollend = function(e) {
    console.log("onscrollend");
};
scwin.checkVal = function() {
    return gridView1.getTopRowIndex() == 3;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하여 2번(setGridHeight(100))을 클릭한다.
    //1. Run the sample file and click twice (setGridHeight (100)).
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 그리드의 높이가 100으로 적용되어 보여진다.
    //1. The height of the grid is shown as 100.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1').style.height == '100px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 1번(setTopRowIndex(7))을 클릭한다.
    //2. Click number 1 (setTopRowIndex (7)).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. rowindex가 7번인 8번row부터 보여진다.(21,22,23)
    //2. The rowindex is displayed starting from row 8 (7, 21, 22, 23)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getTopRowIndex() == 7", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 3번(setGridHeight(200))을 클릭한다.
    //3. Click 3 (setGridHeight (200)).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 4번 row부터 정상적으로 보여진다.(이전에는 아래 공백이 보여짐)
    //3. It will be displayed normally from row 4. (Previous space is shown.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1').style.height == '200px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.G = 9;
    window.u = [];
    for (var i = 0; i < G * 3; i++) {
        u.push(i);
    }
    dataList1.setData(u);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
